/* DWARF original prototype: void TrySyncTime(DESC * this, DWORD dwCurTime, long lNewDelta) */

void __thiscall DESC::TrySyncTime(DESC *this,DWORD dwCurTime,long lNewDelta)

{
  TPacketGCHandshake pack;
  
  pack.bHeader = 0xff;
  pack.dwHandshake = this->m_dwHandshake;
  pack.dwTime = dwCurTime;
  pack.lDelta = lNewDelta;
  Packet(this,&pack,0xd);
  this->m_dwHandshakeSentTime = dwCurTime;
  return;
}
